    "status.ready": "status.ready",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG or ICO. Animated files export their first frame. Metadata is not copied.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG або ICO. Для анімованих файлів експортується перший кадр. Метадані не копіюються.",
    "Transparent areas become white. Animated images use only their first frame.": "Прозорі ділянки стають білими. Для анімованих зображень використовується лише перший кадр.",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG and ICO. Animated files export only their first frame. Output up to 40 megapixels.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG та ICO. З анімованих файлів експортується лише перший кадр. Максимальна роздільна здатність — 40 мегапікселів.",
    "Convert common image formats to JPG, PNG or WebP on your device. Up to 20 files.": "Конвертуйте поширені формати зображень у JPG, PNG або WebP безпосередньо на пристрої. До 20 файлів.",
    "Add up to 20 images. No fixed file-size cap; 20 megapixels per image. Large batches depend on your device memory.": "Додайте до 20 зображень. Немає фіксованого обмеження на розмір файлу; ліміт — 20 мегапікселів на зображення. Обробка великих партій залежить від обсягу пам'яті вашого пристрою.",
    "Images converted. Animated files become a still frame; metadata is not copied.": "Зображення конвертовано. Анімовані файли перетворюються на статичний кадр; метадані не копіюються.",
    "Some files were skipped. Use a supported image format within the on-page limits.": "Деякі файли було пропущено. Використовуйте підтримуваний формат зображення в межах встановлених лімітів.",
    "This image could not be decoded by your browser. Try another file or browser.": "Ваш браузер не зміг розпізнати це зображення. Спробуйте інший файл або браузер.",
    "Choose a supported image format.": "Виберіть підтримуваний формат зображення.",
    "The browser does not support the selected output format.": "Браузер не підтримує вибраний вихідний формат.",
    "Up to 20 images · 20 megapixels per image · no fixed file-size cap. Large batches depend on your device memory.": "До 20 зображень · 20 мегапікселів на зображення · без фіксованого обмеження на розмір файлу. Обробка великих партій залежить від обсягу пам'яті вашого пристрою.",
    "Choose up to 20 images.": "Виберіть до 20 зображень.",
    "AVIF and some HEIC files may depend on browser support.": "Підтримка файлів AVIF і деяких HEIC залежить від можливостей браузера.",
    "AVIF and some HEIC inputs depend on browser support. Animated GIF, APNG and WebP files become a still image. SVG is rasterized, not converted into an editable vector. Metadata is not copied.": "Підтримка вхідних файлів AVIF і деяких HEIC залежить від можливостей браузера. Анімовані файли GIF, APNG та WebP перетворюються на статичні зображення. Файли SVG раструються, а не конвертуються у векторний формат для редагування. Метадані не копіюються.",
    "Multi-page TIFF uses only its first page. Some TIFF compression variants may not decode.": "З багатосторінкового файлу TIFF використовується лише перша сторінка. Деякі варіанти стиснення TIFF можуть не розпізнаватися.",
    "Choose a DOCX, XLSX or PPTX file": "Виберіть файл DOCX, XLSX або PPTX",
    "Files stay on your device. Limits: 100 MB input, 200 MB expanded data and 5,000 package parts.": "Файли залишаються на вашому пристрої. Обмеження: 100 МБ для вхідного файлу, 200 МБ для розпакованих даних і 5000 елементів пакета.",
    "This safely recompresses the Office package without rewriting its contents. Embedded photos are not recompressed, so the result may not be smaller. Signed, encrypted, macro-enabled and older Office files are not supported. Keep your original.": "Цей процес безпечно перестискає пакет Office без зміни його вмісту. Вбудовані фотографії не перестискаються, тому розмір файлу може не зменшитися. Файли Office із цифровим підписом, шифруванням, макросами або застарілих форматів не підтримуються. Збережіть оригінал.",
    "Try to reduce file size": "Спробуйте зменшити розмір файлу",
    "Processing runs locally in this browser. No upload.": "Обробка виконується локально в цьому браузері. Файл не завантажується на сервер.",
    "Recompressing the Office package on your device…": "Перестискання пакета Office на вашому пристрої…",
    "This package is already compact. No smaller download was created.": "Цей пакет уже компактний. Меншу версію файлу не створено.",
    "A smaller copy is ready. Compare it and keep your original.": "Меншу копію створено. Порівняйте її з оригіналом і збережіть оригінал.",
    "The file could not be safely recompressed. Your original has not changed.": "Файл не вдалося безпечно перестиснути. Ваш оригінал залишився без змін.",
    "Processing canceled. Your original file is unchanged.": "Обробку скасовано. Ваш оригінальний файл залишився без змін.",
    "Choose a modern DOCX, XLSX or PPTX file.": "Виберіть сучасний файл DOCX, XLSX або PPTX.",
    "This file is larger than the 100 MB local processing limit.": "Розмір цього файлу перевищує ліміт локальної обробки (100 МБ).",
    "The expanded package exceeds the 200 MB local processing limit.": "Розмір розпакованого пакета перевищує ліміт локальної обробки (200 МБ).",
    "Encrypted Office packages are not supported.": "Зашифровані пакети Office не підтримуються.",
    "Signed or macro-enabled Office files are not supported, to avoid invalidating signatures or macros.": "Файли Office із цифровим підписом або макросами не підтримуються, щоб уникнути пошкодження підписів чи макросів.",
    "The selected file is not a valid modern Office document of that type.": "Вибраний файл не є дійсним сучасним документом Office відповідного типу.",
    "Choose an audio file": "Виберіть аудіофайл",
