    "Choose a file (up to 25 MB)": "Виберіть файл (до 25 МБ)",
    "Your file is processed on this device and is not uploaded.": "Файл обробляється на вашому пристрої та не завантажується на сервер.",
    "Create SHA-256 checksum": "Створити контрольну суму SHA-256",
