    "Extract page ranges": "Витягти діапазони сторінок",
    "Compress a PDF (image-based)": "Стиснути PDF (на основі зображень)",
    "Choose PDF file(s) (up to 10 MB each)": "Виберіть PDF-файл(и) (до 10 МБ кожен)",
    "PDF files stay on this device. Choose up to 10 files.": "PDF-файли залишаються на цьому пристрої. Виберіть до 10 файлів.",
    "Page ranges (for example: 1-3, 5-7)": "Діапазони сторінок (наприклад, 1–3, 5–7)",
    "Each range becomes a separate PDF file.": "Кожен діапазон стане окремим PDF-файлом.",
    "Important before you continue": "Важлива інформація перед продовженням",
    "Pages become images. Text will not be selectable and links, forms and signatures are not kept. The new file can be larger than the original.": "Сторінки перетворюються на зображення. Текст не можна буде виділити; посилання, форми та підписи не зберігаються. Новий файл може бути більшим за оригінал.",
    "I understand. Keep my original PDF.": "Я розумію. Зберегти мій оригінальний PDF.",
