    "Table pages": "Сторінки таблиці",
    "Choose a QR image": "Виберіть зображення з QR-кодом",
    "The image is scanned on your device. Nothing is uploaded.": "Сканування зображення відбувається на вашому пристрої. Дані не завантажуються на сервер.",
    "Start camera": "Увімкнути камеру",
