    "Transcription complete. Review names and numbers.": "Розшифрування завершено. Перевірте імена та цифри.",
    "No speech detected. Try clearer audio or choose a language.": "Мову не розпізнано. Спробуйте використати чіткіший аудіозапис або виберіть мову.",
    "Copied to clipboard.": "Скопійовано в буфер обміну.",
    "Copy was blocked. Select the text and copy it manually.": "Копіювання заблоковано. Виділіть текст і скопіюйте його вручну.",
    "Text file downloaded.": "Текстовий файл завантажено.",
    "This file or codec could not be processed. Try another supported format.": "Цей файл або кодек не вдалося обробити. Спробуйте інший підтримуваний формат.",
    "For long or high-resolution media, a desktop or laptop is recommended. Keep this tab open; speed, memory and battery depend on your device.": "Для довгих медіафайлів або файлів із високою роздільною здатністю рекомендовано використовувати настільний комп’ютер або ноутбук. Не закривайте цю вкладку; швидкість, використання пам’яті та заряд акумулятора залежать від вашого пристрою.",
    "Re-encoding can reduce sound quality or make a larger file. Your original stays unchanged.": "Перекодування може погіршити якість звуку або збільшити розмір файлу. Оригінальний файл залишиться без змін.",
    "First use downloads about 58 MB of model and local engine. Your recording is not uploaded; the browser may download them again if its cache is cleared.": "Під час першого використання завантажується близько 58 МБ даних моделі та локального рушія. Ваш запис не завантажується на сервер; браузер може завантажити ці дані повторно, якщо кеш буде очищено.",
    "Your file is processed locally and is not uploaded.": "Ваш файл обробляється локально й не завантажується на сервер.",
