    "Choose files or a ZIP archive": "Виберіть файли або ZIP-архів",
    "Up to 200 files and 250 MB expanded data. ZIP64 and password-protected files are not supported.": "До 200 файлів і 250 МБ розпакованих даних. Формат ZIP64 і файли, захищені паролем, не підтримуються.",
