    "Start background removal": "Почати видалення фону",
    "The first use loads about 6.6 MB from this site. The photo is processed on your device. A computer is recommended for large images.": "Під час першого використання завантажується близько 6,6 МБ даних із цього сайту. Обробка фото відбувається на вашому пристрої. Для зображень великого розміру рекомендовано використовувати комп'ютер.",
