    "Expression": "Вираз",
    "Supports arithmetic, powers, percentages, trigonometry, roots and logarithms.": "Підтримує арифметичні дії, піднесення до степеня, відсотки, тригонометрію, корені та логарифми.",
    "Use radians (otherwise degrees)": "Використовувати радіани (інакше — градуси)",
