    "Check the selected file and settings, then try again.": "Перевірте вибраний файл і налаштування, а потім спробуйте ще раз.",
    "Up to 200 files; 100 MB total or expanded. ZIP64 and password-protected files are not supported. Large archives use device memory; a computer is recommended.": "До 200 файлів; загальний розмір (або розмір після розпакування) — до 100 МБ. Формат ZIP64 і файли, захищені паролем, не підтримуються. Великі архіви використовують пам'ять пристрою; рекомендовано використовувати комп'ютер.",
